css:
/* 時間割 */
.tt{display:grid;grid-template-columns:56px repeat(6,1fr);grid-auto-rows:26px}
.blk{grid-column:var(--d);grid-row:var(--s)/span var(--n);
     margin:var(--off,0) 6px 0;border-radius:10px;background:#fff;display:grid;place-items:center}
/* 棒2本だけのグラフ（軸・目盛り・凡例は作らない） */
.bars{display:flex;align-items:flex-end;justify-content:center;gap:48px;height:110px;border-bottom:1px solid #ddd}
.bar{width:56px;height:calc(var(--v)/600*100%);background:#2b8fd6}
/* 県タイル地図 */
.pref{position:absolute;background:#1b3b5f;color:#fff;font-size:9px;border-radius:2px;padding:2px 3px}
/* 通話タイル */
.tiles{display:grid;grid-template-columns:repeat(7,1fr);gap:3px;background:#000}
.tiles>*{aspect-ratio:16/10;background:var(--c)}
